import Foundation
import CoreGraphics
import CoreVideo
import CoreImage
import XCTest

final class NativeRenderingTests:XCTestCase {
 func solid(_ color:CGColor,width:Int=8,height:Int=8)->CGImage {avatarDrawingImage(size:CGSize(width:width,height:height)) {size,context in context.setFillColor(color);context.fill(CGRect(origin:.zero,size:size));return true}!}
 let red=CGColor(colorSpace:CGColorSpaceCreateDeviceRGB(),components:[1,0,0,1])!,blue=CGColor(colorSpace:CGColorSpaceCreateDeviceRGB(),components:[0,0,1,1])!
 func pixel(_ image:CGImage,_ x:Int,_ y:Int)->[UInt8] {let c=CGContext(data:nil,width:image.width,height:image.height,bitsPerComponent:8,bytesPerRow:image.width*4,space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGImageAlphaInfo.premultipliedLast.rawValue|CGBitmapInfo.byteOrder32Big.rawValue)!;c.draw(image,in:CGRect(x:0,y:0,width:image.width,height:image.height));let p=c.data!.assumingMemoryBound(to:UInt8.self);let i=y*c.bytesPerRow+x*4;return Array(UnsafeBufferPointer(start:p+i,count:4))}
 func testCenteredFrameMatchesExistingGeometry() {XCTAssertEqual(avatarDrawingFrame(size:CGSize(width:640,height:640),zoom:0.5,offset:.zero),CGRect(x:160,y:160,width:320,height:320))}
 func testOffsetDirectionAndScalePreserved() {XCTAssertEqual(avatarDrawingFrame(size:CGSize(width:640,height:640),zoom:0.5,offset:CGPoint(x:3,y:3)),CGRect(x:320,y:0,width:320,height:320))}
 func testInvalidZoomAndOffsetRejected() {for zoom:CGFloat in [0,-1,.nan,.infinity,-.infinity,.greatestFiniteMagnitude] {XCTAssertNil(avatarDrawingFrame(size:CGSize(width:640,height:640),zoom:zoom,offset:.zero))};for value:CGFloat in [.nan,.infinity,-.infinity] {XCTAssertNil(avatarDrawingFrame(size:CGSize(width:640,height:640),zoom:1,offset:CGPoint(x:value,y:0)));XCTAssertNil(avatarDrawingFrame(size:CGSize(width:640,height:640),zoom:1,offset:CGPoint(x:0,y:value)))}}
 func testInvalidCanvasSizesDoNotDraw() {for size in [CGSize.zero,CGSize(width:-1,height:5),CGSize(width:1.5,height:2),CGSize(width:CGFloat.infinity,height:1),CGSize(width:CGFloat.nan,height:1),CGSize(width:CGFloat(Int.max),height:2)] {XCTAssertNil(avatarDrawingImage(size:size) {_,_ in XCTFail();return true})}}
 func testCompositedImagePreservesSourcePixelDimensions() throws {let image=try XCTUnwrap(avatarCompositedImage(from:solid(red,width:8,height:6),zoom:0.5,offset:.zero,background:solid(blue)));XCTAssertEqual(image.width,8);XCTAssertEqual(image.height,6)}
 func testCompositingDrawsForegroundAndBackground() throws {let image=try XCTUnwrap(avatarCompositedImage(from:solid(red),zoom:0.5,offset:.zero,background:solid(blue)));XCTAssertEqual(pixel(image,0,0),[0,0,255,255]);XCTAssertEqual(pixel(image,4,4),[255,0,0,255])}
 func testPositiveXOffsetMovesForegroundRight() throws {let image=try XCTUnwrap(avatarCompositedImage(from:solid(red),zoom:0.5,offset:CGPoint(x:3,y:0),background:solid(blue)));XCTAssertEqual(pixel(image,1,4),[0,0,255,255]);XCTAssertEqual(pixel(image,6,4),[255,0,0,255])}
 func testTransparentAreaRemainsTransparentWithoutBackground() throws {let image=try XCTUnwrap(avatarCompositedImage(from:solid(red),zoom:0.5,offset:.zero));XCTAssertEqual(pixel(image,0,0),[0,0,0,0]);XCTAssertEqual(pixel(image,4,4),[255,0,0,255])}
 func testFlippedCanvasReversesVerticalDrawing() throws {func image(_ flipped:Bool)->CGImage? {avatarDrawingImage(size:CGSize(width:4,height:4),flipped:flipped) {_,c in c.setFillColor(self.blue);c.fill(CGRect(x:0,y:0,width:4,height:4));c.setFillColor(self.red);c.fill(CGRect(x:0,y:0,width:4,height:2));return true}};let normal=try XCTUnwrap(image(false)),flipped=try XCTUnwrap(image(true));XCTAssertNotEqual(pixel(normal,1,0),pixel(flipped,1,0));XCTAssertEqual(pixel(normal,1,0),pixel(flipped,1,3))}
 func testDrawingFailureDoesNotReturnPartialImage() {XCTAssertNil(avatarDrawingImage(size:CGSize(width:8,height:8)) {_,_ in false})}
 func testRealPixelBufferContainsCompositedPixels() throws {let buffer=try XCTUnwrap(avatarPixelBuffer(from:solid(red),zoom:0.5,background:solid(blue)));XCTAssertEqual(CVPixelBufferGetWidth(buffer),8);XCTAssertEqual(CVPixelBufferGetHeight(buffer),8);let ci=CIImage(cvPixelBuffer:buffer);let image=try XCTUnwrap(CIContext().createCGImage(ci,from:ci.extent));let outer=pixel(image,0,0),center=pixel(image,4,4);XCTAssertGreaterThan(outer[2],240);XCTAssertLessThan(outer[0],15);XCTAssertGreaterThan(center[0],240);XCTAssertLessThan(center[2],15)}
 func testInvalidGeometryRejectsNativePixelBufferAndImage() {let image=solid(red);XCTAssertNil(avatarPixelBuffer(from:image,zoom:0));XCTAssertNil(avatarCompositedImage(from:image,zoom:1,offset:CGPoint(x:CGFloat.nan,y:0)))}
}
